import json
import re
from pathlib import Path

data = json.loads(
    Path("data/processed/apple_annual_report_chunks.json").read_text(encoding="utf-8")
)

topics = {
    "Revenue": ["total net sales", "net sales", "revenue"],
    "Research and Development": ["research and development", "R&D"],
    "Gross Margin": ["gross margin", "gross profit"],
    "Operating Expenses": ["operating expenses", "selling, general and administrative"],
    "Cash Flow": ["cash generated by operating activities", "operating activities", "cash flow"],
    "Debt and Liquidity": ["long-term debt", "commercial paper", "liquidity"],
    "Business Segments": ["Americas", "Europe", "Greater China", "Japan", "Rest of Asia Pacific"],
    "Products": ["iPhone", "Mac", "iPad", "Wearables"],
    "Services": ["Services net sales", "services gross margin"],
    "Risk Factors": ["risk factors", "foreign currency", "competition"],
    "Inventory": ["inventories", "inventory"],
    "Shareholders": ["dividends", "share repurchases", "common stock"]
}

for topic, keywords in topics.items():
    print("\n" + "=" * 85)
    print("TOPIC:", topic)
    print("=" * 85)

    matches = []

    for chunk in data["chunks"]:
        text = chunk["text"]
        if any(keyword.lower() in text.lower() for keyword in keywords):
            matches.append(chunk)

    print("Matching chunks:", len(matches))

    for chunk in matches[:3]:
        print("\nChunk ID:", chunk["chunk_id"])
        print("Page:", chunk["page_number"])
        print("Text preview:")
        print(re.sub(r"\s+", " ", chunk["text"])[:700])
